{
  "name": "opencode-minimax-easy-vision-cli",
  "version": "1.0.1",
  "description": "OpenCode plugin that adds vision support for text-only models — paste images and the plugin analyzes them via a vision CLI tool (e.g., mmx vision describe)",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "files": [
    "dist",
    "opencode-minimax-easy-vision-cli.example.jsonc",
    "AGENT_SETUP.md",
    "CONFIGURATION.md"
  ],
  "scripts": {
    "build": "tsc",
    "format": "prettier --write src/**/*.ts",
    "format:check": "prettier --check src/**/*.ts",
    "prepublishOnly": "npm run build",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "minimax",
    "vision",
    "image",
    "cli"
  ],
  "author": "Devadathan M B <devadathanmb@gmail.com>",
  "license": "AGPL-3.0",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.2.26",
    "@types/node": "^25.0.0",
    "husky": "^9.1.7",
    "prettier": "^3.8.1",
    "typescript": "^5.7.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/devadathanmb/opencode-minimax-easy-vision"
  },
  "dependencies": {
    "strip-json-comments": "^5.0.3"
  }
}
